{"file_path":"/work/tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5


def test_empty_rates():
    assert monitor_flag_rate([]) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_pool_weights_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 6), (5, 7)])
def test_trailing_window(days, expected):
    assert flags_in_window([1, 2, 4], days) == expected


def test_parse_skips_comments_and_blanks_and_strips_fields():
    lines = ["", " \t", "  # header", " a , 1 , 1 ", "b, 2, 0", " c,3, "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,2", "a,2,1,b", "a,x,1"])
def test_parse_errors_include_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "a,1,0", "", bad_line])


def test_dedupe_keeps_last_record_not_latest_day():
    old = {"id": "b", "day": 5, "flagged": True}
    last = {"id": "b", "day": 2, "flagged": False}
    earlier_day = {"id": "z", "day": 1, "flagged": True}
    same_day = {"id": "a", "day": 2, "flagged": True}
    assert dedupe_transcripts([old, same_day, earlier_day, last]) == [earlier_day, same_day, last]


def test_daily_counts_include_gaps_and_respect_bounds():
    events = [{"day": day, "flagged": True} for day in [0, 1, 1, 3, 4]]
    events.append({"day": 2, "flagged": False})
    assert daily_flag_counts(events, 1, 3) == [2, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [{"day": 1, "flagged": True}], "b": [{"day": 4, "flagged": False}] * 2, "c": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rankings_and_rates():
    groups = {"z": [{"flagged": True}], "empty": [], "b": [{"flagged": False}], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0)]


def test_streak_resets_on_nonpositive_days():
    assert longest_flag_streak([1, 0, 2, 3, -1, 4]) == 2
    assert longest_flag_streak([]) == 0
